import type React from 'react'
import {useEffect, useId, useMemo, useRef, useState} from 'react'
import {Button, Heading, IconButton, Link} from '@primer/react'
import {XIcon, LightBulbIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import {useClickAnalytics} from '@github-ui/use-analytics'

import Styles from './Tip.module.css'

export interface TipProps {
  title: string
  hotspot?: string
  body: string
  link?: {
    label: string
    href: string
  }
  // Current URL/path for analytics
  currentUrl?: string
  // Business/Enterprise ID for analytics
  businessId?: string
  // User ID for analytics
  userId?: string
  // Organization ID for analytics
  organizationId?: string
  // Nudge group for analytics
  group: string
  // Nudge location for analytics
  location: string
  // Nudge category for analytics
  category: string
  // CTA action for analytics
  action: string
  // Adjusts the positioning. The margins' value can be tweaked in the CSS file.
  isFloating?: boolean
  // Whether to flash the expanded state on mount
  hasIntro?: boolean
  // Callback triggered once the intro completes
  onIntroComplete?: () => void
  // Callback triggered when the user dismisses the tip
  onDismiss: () => void
}

const Tip: React.FC<TipProps> = ({
  title,
  hotspot,
  body,
  link,
  currentUrl,
  businessId,
  userId,
  organizationId,
  group,
  location,
  category,
  action,
  isFloating = true,
  hasIntro = true,
  onIntroComplete,
  onDismiss,
}) => {
  const [isOpen, setIsOpen] = useState<boolean>(false)
  const [isPlayingIntro, setIsPlayingIntro] = useState<boolean>(false)
  const introTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null)
  const toggleRef = useRef<HTMLButtonElement>(null)

  const headingId = useId()

  const {sendClickAnalyticsEvent} = useClickAnalytics()

  useEffect(() => {
    const proceed = () => {
      if (hasIntro) {
        if (introTimeoutRef.current) clearTimeout(introTimeoutRef.current)

        introTimeoutRef.current = setTimeout(() => {
          setIsPlayingIntro(true)

          introTimeoutRef.current = setTimeout(() => {
            setIsPlayingIntro(false)
            onIntroComplete?.()
          }, 2000)
        }, 500)
      } else {
        onIntroComplete?.()
      }
    }

    proceed()

    return () => {
      if (introTimeoutRef.current) clearTimeout(introTimeoutRef.current)
    }
  }, [hasIntro, onIntroComplete])

  const toggleDOM = useMemo(
    () => (
      <button
        ref={toggleRef}
        className={clsx(Styles['Tip__toggle'], isPlayingIntro && Styles['Tip__toggle--isHighlighted'])}
        onClick={() => {
          setIsOpen(!isOpen)
        }}
        aria-haspopup="dialog"
        aria-expanded={isOpen ? 'true' : 'false'}
        aria-describedby={headingId}
      >
        {isOpen ? <XIcon data-testid="closeButton" size={16} /> : <LightBulbIcon data-testid="openButton" size={16} />}
        <div className={Styles['Tip__toggleLabel']}>
          <div className={Styles['Tip__toggleLabelContent']}>
            <div className={Styles['Tip__toggleLabelText']}>{title}</div>
          </div>
        </div>
      </button>
    ),
    [isPlayingIntro, isOpen, headingId, title],
  )

  const contentDOM = useMemo(
    () => (
      <div className={Styles['Tip__content']} role="dialog" aria-modal="true" aria-label={title}>
        <IconButton
          className={Styles['Tip__dismiss']}
          variant="invisible"
          icon={XIcon}
          size="small"
          aria-label="Dismiss"
          data-testid="tip-dismiss-button"
          onClick={() => {
            sendClickAnalyticsEvent({
              action: `${action}_dismiss`,
              group,
              location,
              category,
              label: `enterprise_id:${businessId || 'unknown'};user_id:${userId || 'unknown'};organization_id:${organizationId || 'unknown'};location:${currentUrl || 'unknown'};content:${title}`,
            })
            onDismiss()
          }}
        />
        <div className={Styles['Tip__contentHeadingBlock']}>
          <Heading id={headingId} as="h2" className={Styles['Tip__contentHeading']}>
            {title}
          </Heading>
          {hotspot && (
            <Heading as="h2" className={Styles['Tip__hotspot']}>
              {hotspot}
            </Heading>
          )}
        </div>

        <p className={Styles['Tip__body']}>{body}</p>

        {link && (
          <Button
            as="a"
            href={link.href}
            variant="primary"
            onClick={() => {
              sendClickAnalyticsEvent({
                category,
                action,
                label: `enterprise_id:${businessId || 'unknown'};user_id:${userId || 'unknown'};location:${currentUrl || 'unknown'};content:${link.label}`,
              })
            }}
          >
            {link.label}
          </Button>
        )}

        <hr className={Styles['Tip__divider']} />
        <p className={Styles['Tip__body']}>
          Configure tips in your{' '}
          <Link inline href="/settings/notifications">
            notification settings
          </Link>
        </p>
      </div>
    ),
    [
      title,
      headingId,
      hotspot,
      body,
      link,
      currentUrl,
      sendClickAnalyticsEvent,
      businessId,
      userId,
      organizationId,
      onDismiss,
      action,
      category,
      group,
      location,
    ],
  )

  return (
    <div className={clsx(Styles['Tip'], isOpen && Styles['Tip--isOpen'], isFloating && Styles['Tip--isFloating'])}>
      {toggleDOM}
      {contentDOM}
    </div>
  )
}

export {Tip}
export default Tip
